def walk(d, acc):
    for e in repo.list(d):
        p = (d.rstrip("/") + "/" + e) if d != "." else e
        if e.endswith("/"):
            walk(p, acc)
        else:
            acc.append(p)
    return acc

src_files = walk("src/", [])
all_files = walk(".", [])
out = []
for f in src_files:
    c = repo.read(f, missing_ok=True)
    out.append({"path": f, "len": len(c) if c != None else None, "slow": c.count("slow_path") if c else 0, "fast": c.count("fast_path") if c else 0})
return {"src_files": out, "all_files": all_files}

